export type IconKeys = keyof typeof ICONS;

interface Props {
  icon: IconKeys;
  size?: number;
  color?: string;
  className?: string;
  style?: CSSProperties
}

export function Icon({
  icon,
  size = 24,
  color = "var(--text-second)",
  className,
  style
}: Props) {
  return (
    <svg
      width={size}
      height={size}
      fill={color}
      viewBox="0 0 24 24"
      style={{...style, verticalAlign:"middle"}}
      className={className}
    >
      {ICONS[icon]}
    </svg>
  );
}

